<?phpsession_start();require_once("setgetcon.php");$dbi=new Database();$con=$dbi->getConnection();if(isset($_POST["qual"]) and !empty($_POST["qual"])){    //Fetch all state data    $query = $con->prepare("SELECT * FROM levels WHERE depcode = ? ORDER BY levelname ASC");    $query->execute([$_POST["qual"]]);    //Count total number of rows    $rowCount = $query->rowCount();        //State option list    if($rowCount > 0){        echo '<option value="">Choose level</option>';        while($row = $query->fetch()){             echo '<option value="'.$row['levelcode'].'">'.$row['levelname'].'</option>';        }    }else{        echo '<option value="">Levels not available</option>';    }}?>